<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\ValueObject\Accessor\TenantLoginProviderPrivateKeyAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantLoginProviderPrivateKeyAccessor trait.
 *
 * Covers null default, string/VO assignment via withPrivateKey,
 * getPrivateKey/privateKey accessors, and isPrivateKeyChanged with/without original.
 */
class TenantLoginProviderPrivateKeyAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withPrivateKey creates a new instance with the PrivateKey set
     * from a string value, and getPrivateKey returns the primitive string.
     */
    public function testWithPrivateKeyFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderPrivateKeyAccessorUnitTest();

        // Act
        $result = $holder->withPrivateKey('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getPrivateKey());
    }
    /**
     * Asserts that withprivateKey has access to the value object
     * from a string value, and getPrivateKey returns the primitive string.
     */
    public function testWithPrivateKeyFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderPrivateKeyAccessorUnitTest();

        // Act
        $result = $holder->withPrivateKey('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->privateKey()->value());
    }
    public function testChangedPrivateKey(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderPrivateKeyAccessorUnitTest();
        $original = $holder->withPrivateKey('one');
        $same = $holder->withPrivateKey('one');
        $modified = $holder->withPrivateKey('other');

        // Act
        $unchanged = $holder->isPrivateKeyChanged();
        $withSame = $original->isPrivateKeyChanged($same);
        $withDiferent = $original->isPrivateKeyChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantLoginProviderPrivateKeyAccessorUnitTest
{
    use TenantLoginProviderPrivateKeyAccessor;
}
